import subprocess
from dataclasses import dataclass

from agents import function_tool


@dataclass
class MigrationResult:
    environment: str
    exit_code: int
    output_tail: str


@function_tool
def run_flag_migration_script(environment: str, dry_run: bool = True) -> MigrationResult:
    cmd = ["python", "scripts/migrate_flags.py", "--env", environment]
    if dry_run:
        cmd.append("--dry-run")
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
    tail = "\n".join(proc.stdout.strip().splitlines()[-20:])
    return MigrationResult(environment=environment, exit_code=proc.returncode, output_tail=tail)

import sqlite3
import time

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("flag-admin")

DB_PATH = "flags.db"


@mcp.tool()
def purge_stale_flags(
    project_key: str,
    stale_days: int = 90,
    confirm_delete: bool = False,
    max_delete: int = 50,
) -> dict:
    if stale_days < 1:
        return {"ok": False, "error": "stale_days must be at least 1"}
    cutoff = int(time.time()) - stale_days * 86400
    conn = sqlite3.connect(DB_PATH)
    result = {
        "ok": True,
        "project": project_key,
        "stale_days": stale_days,
        "found": [],
        "deleted": [],
        "skipped": [],
        "dry_run": not confirm_delete,
    }
    try:
        rows = conn.execute(
            "SELECT flag_key, last_evaluated_at, enabled FROM flags "
            "WHERE project_key = ? AND COALESCE(last_evaluated_at, 0) < ? "
            "ORDER BY last_evaluated_at",
            (project_key, cutoff),
        ).fetchall()
        for flag_key, last_eval, enabled in rows:
            result["found"].append(
                {"key": flag_key, "last_evaluated_at": last_eval, "enabled": bool(enabled)}
            )
        if confirm_delete:
            for flag_key, last_eval, enabled in rows:
                if enabled:
                    result["skipped"].append({"key": flag_key, "reason": "still enabled"})
                    continue
                if len(result["deleted"]) >= max_delete:
                    result["skipped"].append({"key": flag_key, "reason": "limit reached"})
                    continue
                conn.execute(
                    "DELETE FROM flags WHERE project_key = ? AND flag_key = ?",
                    (project_key, flag_key),
                )
                result["deleted"].append(flag_key)
            conn.commit()
    finally:
        conn.close()
    result["found_count"] = len(result["found"])
    result["deleted_count"] = len(result["deleted"])
    return result
